const { id: submissionId } = await params
const body = BulkReachRecordsSchema.safeParse(await request.json().catch(() => null))
if (!body.success) {
  return Response.json({ error: 'validation_error', details: body.error.flatten() }, { status: 400 })
}

const supabase = await createClient()
const { data: sub, error: subError } = await getSubmissionForStudio(supabase, submissionId, auth.studioId)
if (subError || !sub) return Response.json({ error: 'not_found' }, { status: 404 })

// Build insert rows — reach_compliant is server-derived (C10: not client-controlled).
// Default to false with source 'artist_claimed' until a registry check is available (Sprint 10).
const rows = body.data.records.map((r) => ({
  submission_id: submissionId,
  booking_id: sub.booking_id ?? null,
  studio_id: auth.studioId,
  ink_brand: r.ink_brand,
  ink_color: r.ink_color,
  ink_product_code: r.ink_product_code ?? null,
  batch_number: r.batch_number,
  manufacture_date: r.manufacture_date ?? null,
  expiry_date: r.expiry_date ?? null,
  // C10: server sets reach_compliant = false until registry is implemented in Sprint 10.
  // source = 'artist_claimed' documents that no verified registry match was checked.
  reach_compliant: false,
  reach_compliance_source: 'artist_claimed' as const,
  sds_url: r.sds_url ?? null,
}))

const { data, error } = await supabase
  .from('reach_ink_records')
  .insert(rows)
  .select()

if (error) {
  logger.error({ err: error, submissionId }, 'reach records bulk insert failed')
  return Response.json({ error: 'database_error' }, { status: 500 })
}

await logAuditAction(
  auth.user.id,
  'reach_record.created',
  { type: 'reach_ink_record', id: submissionId },
  { submission_id: submissionId, count: data.length },
  auth.studioId
)
return Response.json({ data }, { status: 201 })

